def close(self) -> None:
    self.parent = None
    if not self._tasks and not self._children:
        self._mark_abandoned()

        self.effectively_cancelled = False
        for task in self._children:
            task._attempt_delivery_of_any_pending_cancel()
        for child in self._tasks:
            child.recalculate()

